use crate::common;
use rust_xlsxwriter::{PivotTable, PivotTableValueField, Workbook, XlsxError};

// Create a rust_xlsxwriter file to compare against an Excel file.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    // Write the headers.
    worksheet.write_string(2, 1, "Region")?;
    worksheet.write_string(2, 2, "Item")?;
    worksheet.write_string(2, 3, "Volume")?;
    worksheet.write_string(2, 4, "Month")?;

    // Write the data used in the pivot table.
    let data = common::get_autofilter_data();
    for (row, data) in data.iter().enumerate() {
        let row = 3 + row as u32;
        worksheet.write_string(row, 1, data.0)?;
        worksheet.write_string(row, 2, data.1)?;
        worksheet.write_number(row, 3, data.2)?;
        worksheet.write_string(row, 4, data.3)?;
    }

    let pivot_table = PivotTable::new()
        .set_data_source(("Sheet1", 2, 1, 52, 4))
        .add_row_field("Region")
        .add_value_field(&PivotTableValueField::new("Volume"));

    let worksheet = workbook.add_worksheet();
    worksheet.add_pivot_table(2, 0, &pivot_table)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_pivot_table20() {
    let test_runner = common::TestRunner::new()
        .set_name("pivot_table20")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
